FILE rules.js sha256=f60f2004db754f0149513b86c76e0b6c9a41c5896ee9c933b911502d8b8192c2 utf8_bytes=204
const Rules = {
  maxDist: 3,
  canInteract(player, x, y, z) {
    const dx = x - player.x, dy = y - player.y, dz = z - player.z;
    return Math.sqrt(dx * dx + dy * dy + dz * dz) <= this.maxDist;
  }
};

END FILE

