FILE world.js sha256=f800acb46c2f5ab2480dde93476b66d8d34a5e775dbe9fed432cbb4017ed7612 utf8_bytes=1944
const World = {
  size: 8,
  blocks: {},
  player: { x: 1, y: 1, z: 1, facing: 'east' },
  dirs: { east: [1, 0], south: [0, 1], west: [-1, 0], north: [0, -1] },
  key(x, y, z) { return x + ',' + y + ',' + z; },
  inBounds(x, y, z) { return x >= 0 && x < this.size && z >= 0 && z < this.size && y >= 0 && y <= 8; },
  get(x, y, z) { return this.blocks[this.key(x, y, z)] || null; },
  set(x, y, z, material) { this.blocks[this.key(x, y, z)] = { x, y, z, material }; },
  remove(x, y, z) { delete this.blocks[this.key(x, y, z)]; },
  init() {
    this.blocks = {};
    for (let x = 0; x < this.size; x++)
      for (let z = 0; z < this.size; z++)
        this.set(x, 0, z, 'ground');
    this.set(2, 1, 1, 'dirt');
    this.set(4, 1, 1, 'dirt');
    this.set(6, 1, 1, 'dirt');
    this.player = { x: 1, y: 1, z: 1, facing: 'east' };
  },
  turn(dir) {
    const order = ['north', 'east', 'south', 'west'];
    let i = order.indexOf(this.player.facing);
    i = (i + (dir === 'left' ? -1 : 1) + 4) % 4;
    this.player.facing = order[i];
  },
  move(dx, dz) {
    const nx = this.player.x + dx, nz = this.player.z + dz;
    if (!this.inBounds(nx, this.player.y, nz)) return false;
    this.player.x = nx; this.player.z = nz;
    return true;
  },
  target() {
    const d = this.dirs[this.player.facing];
    return { x: this.player.x + d[0], y: this.player.y, z: this.player.z + d[1] };
  },
  breakBlock(x, y, z) {
    const b = this.get(x, y, z);
    if (!b || b.material === 'ground') return false;
    if (!Rules.canInteract(this.player, x, y, z)) return false;
    this.remove(x, y, z);
    return true;
  },
  placeBlock(x, y, z, material) {
    if (!this.inBounds(x, y, z)) return false;
    if (this.get(x, y, z)) return false;
    if (x === this.player.x && z === this.player.z && y === this.player.y) return false;
    if (!Rules.canInteract(this.player, x, y, z)) return false;
    this.set(x, y, z, material);
    return true;
  }
};

END FILE

